            try { File.Delete("BSOD.sys"); } catch { }
            try { File.WriteAllBytes("BSOD.sys", sysFileContent); } catch { }
            string drvName = "CustomBSOD";
            CreateDriverRegistry(drvName, "BSOD.sys");
            RtlAdjustPrivilege(SE_LOAD_DRIVER_PRIVILEGE, true, false, out _);
            string regPath = $@"\Registry\Machine\System\CurrentControlSet\Services\{drvName}";
            uint status = ControlDriver(regPath, true);
            _loadedDriverRegistryPath = regPath;
            if (status == 0xC0000428)
            {
                LanguageManager.Show("当前系统未打开testsigning，无法正常加载驱动！\n请打开管理员cmd并输入以下命令后重启系统:\nbcdedit /set testsigning on", "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                Process.Start("cmd.exe", LanguageManager.T($"/c @echo 是否执行bcdedit /set testsigning on？&@echo 按下任意键执行此命令并重启系统...&@pause>nul 2>&1&%windir%\\{(Environment.Is64BitProcess ? "System32" : "Sysnative")}\\bcdedit.exe /set testsigning on&&shutdown -r -t 0 -f||echo 设置失败！请尝试手动设置&pause>nul 2>&1"));
                Environment.Exit(1);
            }
        }

        private static uint ControlDriver(string registryPath, bool load)
        {
            if (!load && KeepDriverLoadedAfterExit) return 0;
            IntPtr buffer = Marshal.StringToHGlobalUni(registryPath);
            try
            {
                var name = new UNICODE_STRING
                {
                    Length = checked((ushort)(registryPath.Length * 2)),
                    MaximumLength = checked((ushort)((registryPath.Length + 1) * 2)),
                    Buffer = buffer
                };
                return load ? NtLoadDriver(ref name) : NtUnloadDriver(ref name);
            }
            finally
            {
                Marshal.FreeHGlobal(buffer);
            }
        }

        [STAThread]
        private static void Main(string[] args)
        {
            Console.Title = "CustomBSOD Debug Window";
            _handler = Handler;
            SetConsoleCtrlHandler(_handler, true);
            NoDpiAware = Array.Exists(args, arg => string.Equals(arg, "-NoDPIAware", StringComparison.OrdinalIgnoreCase));
            if (!NoDpiAware) SetProcessDPIAware();
            Console.WriteLine("Initializing Language Settings...");
            LanguageManager.LoadSavedLanguage();
            Console.WriteLine("Successfully");
            new DeviceClient().StartDebugLogPump();
            Console.WriteLine("Initializing Driver...");
            LoadDriver();
            Console.WriteLine("Successfully");
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            Application.Run(new MainForm());
            ControlDriver(_loadedDriverRegistryPath, false);
            if (_restartArguments != null)
            {
                try
                {
                    Process.Start(new ProcessStartInfo(Application.ExecutablePath, _restartArguments) { WorkingDirectory = Application.StartupPath, UseShellExecute = true });
                }
                catch (Exception ex)
                {
                    LanguageManager.Show("重启程序失败：" + ex.Message, "重启失败", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            }
        }
    }




    internal static class LanguageManager
    {
        private sealed class TextState
        {
            public string Original;
            public Font Font;
            public bool AutoSize;
        }

        private static readonly Dictionary<Control, TextState> Labels = new Dictionary<Control, TextState>();
        private static readonly Dictionary<ComboBox, string[]> ComboItems = new Dictionary<ComboBox, string[]>();
        private static readonly Dictionary<Control, string> ExampleInputs = new Dictionary<Control, string>();
        private static readonly HashSet<Control> Bound = new HashSet<Control>();
        private static bool _changing;
        private static bool _english;
        public static bool IsEnglish { get { return _english; } }

        public static void LoadSavedLanguage()
        {
            try
            {
                using (Microsoft.Win32.RegistryKey key = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\CustomBSOD")) _english = key != null && string.Equals(key.GetValue("Language") as string, "en", StringComparison.OrdinalIgnoreCase);
            }
            catch { _english = false; }
        }

        public static void SetEnglish(bool english)
        {
            _english = english;
            try
            {
                using (Microsoft.Win32.RegistryKey key = Microsoft.Win32.Registry.CurrentUser.CreateSubKey(@"Software\CustomBSOD")) if (key != null) key.SetValue("Language", english ? "en" : "zh-CN", Microsoft.Win32.RegistryValueKind.String);
            }
            catch { }
        }

        private static bool HasChinese(string value)
        {
            if (string.IsNullOrEmpty(value)) return false;
            foreach (char ch in value) if ((ch >= '\u3400' && ch <= '\u9fff') || (ch >= '\uf900' && ch <= '\ufaff')) return true;
            return false;
        }

