        private static readonly List<KeyValuePair<string, string>> ReplacementOrder = BuildReplacementOrder();

        private static List<KeyValuePair<string, string>> BuildReplacementOrder()
        {
            List<KeyValuePair<string, string>> items = new List<KeyValuePair<string, string>>(Translations);
            items.Sort((a, b) => b.Key.Length.CompareTo(a.Key.Length));
            return items;
        }

        public static string T(string text)
        {
            return _english ? ToEnglish(text) : text;
        }

        private static string ToEnglish(string text)
        {
            if (!HasChinese(text)) return text;
            string result;
            if (Translations.TryGetValue(text, out result)) return result;
            result = text;
            foreach (KeyValuePair<string, string> pair in ReplacementOrder) if (result.IndexOf(pair.Key, StringComparison.Ordinal) >= 0) result = result.Replace(pair.Key, pair.Value);
            return result;
        }

        public static DialogResult Show(string message, string caption)
        {
            return MessageBox.Show(T(message), T(caption));
        }

        public static DialogResult Show(string message, string caption, MessageBoxButtons buttons, MessageBoxIcon icon)
        {
            return MessageBox.Show(T(message), T(caption), buttons, icon);
        }

        public static DialogResult Show(IWin32Window owner, string message, string caption, MessageBoxButtons buttons, MessageBoxIcon icon)
        {
            return MessageBox.Show(owner, T(message), T(caption), buttons, icon);
        }

        public static void Attach(Control root)
        {
            if (root == null || !Bound.Add(root)) return;
            TextBoxBase textBox = root as TextBoxBase;
            if (textBox != null)
            {
                if (HasChinese(textBox.Text) && ToEnglish(textBox.Text) != textBox.Text) ExampleInputs[root] = textBox.Text;
            }
            else if (!(root is ComboBox) && !(root is ListBox) && !(root is NumericUpDown))
            {
                Labels.Add(root, new TextState { Original = root.Text, Font = root.Font, AutoSize = root is Label ? ((Label)root).AutoSize : (root is CheckBox && ((CheckBox)root).AutoSize) });
                root.TextChanged += OnControlTextChanged;
            }
            ComboBox combo = root as ComboBox;
            if (combo != null && !string.Equals(combo.Tag as string, "LanguageSwitcher", StringComparison.Ordinal))
            {
                string[] originals = new string[combo.Items.Count];
                bool hasStrings = false;
                for (int i = 0; i < combo.Items.Count; i++)
                {
                    originals[i] = combo.Items[i] as string;
                    if (HasChinese(originals[i])) hasStrings = true;
                }
                if (hasStrings) ComboItems[combo] = originals;
            }
            root.ControlAdded += delegate (object sender, ControlEventArgs e) { Attach(e.Control); };
            root.Disposed += delegate
            {
                Bound.Remove(root);
                Labels.Remove(root);
                ExampleInputs.Remove(root);
                if (combo != null) ComboItems.Remove(combo);
            };
            foreach (Control child in root.Controls) Attach(child);
            ApplySingle(root);
        }

        private static void OnControlTextChanged(object sender, EventArgs args)
        {
            if (_changing) return;
            Control control = (Control)sender;
            TextState state;
            if (Labels.TryGetValue(control, out state))
            {
                state.Original = control.Text;
                ApplySingle(control);
            }
        }

        public static void Refresh(Control root)
        {
            if (root == null) return;
            ApplySingle(root);
            foreach (Control child in root.Controls) Refresh(child);
            ListBox list = root as ListBox;
            if (list != null && list.Items.Count > 0)
            {
                int selected = list.SelectedIndex;
                list.BeginUpdate();
                try
                {
                    for (int i = 0; i < list.Items.Count; i++) list.Items[i] = list.Items[i];
                    if (list.SelectedIndex != selected) list.SelectedIndex = selected;
                }
                finally { list.EndUpdate(); }
                list.Invalidate();
            }
        }

        private static void ApplySingle(Control control)
        {
            if (_changing || control.IsDisposed) return;
            TextState state;
            if (Labels.TryGetValue(control, out state))
            {
                _changing = true;
                try
                {
                    string translated = _english ? T(state.Original) : state.Original;
                    if (control.Text != translated) control.Text = translated;
                    FitText(control, state);
                }
                finally { _changing = false; }
            }
            string sample;
            TextBoxBase textBox = control as TextBoxBase;
            if (textBox != null && !textBox.Modified && ExampleInputs.TryGetValue(control, out sample))
            {
                string translated = _english ? T(sample) : sample;
                if (textBox.Text == sample || textBox.Text == ToEnglish(sample))
                    if (textBox.Text != translated) { textBox.Text = translated; textBox.Modified = false; }
            }
            ComboBox combo = control as ComboBox;
            string[] originalItems;
            if (combo != null && ComboItems.TryGetValue(combo, out originalItems) && combo.Items.Count == originalItems.Length)
            {
                combo.BeginUpdate();
                try
                {
                    for (int i = 0; i < originalItems.Length; i++)
                    {
                        if (originalItems[i] == null) continue;
                        string newText = _english ? T(originalItems[i]) : originalItems[i];
                        if (!object.Equals(combo.Items[i], newText)) combo.Items[i] = newText;
                    }
                }
                finally { combo.EndUpdate(); }
            }
        }

        private static void FitText(Control control, TextState state)
        {
            if (control is ModernButton) return;
            CheckBox check = control as CheckBox;
            if (check != null)
            {
                if (!_english)
                {
                    check.Font = state.Font;
                    check.AutoSize = state.AutoSize;
                    return;
                }
                if (check.Parent == null || check.Parent.ClientSize.Width < 100) return;
                if (check.Parent is FlowLayoutPanel) return;
                int available = Math.Max(64, check.Parent.ClientSize.Width - check.Left - 8);
                foreach (Control other in check.Parent.Controls) if (other != check && other.Visible && other.Left > check.Left && other.Top < check.Bottom && other.Bottom > check.Top) available = Math.Max(64, Math.Min(available, other.Left - check.Left - 8));
                Font candidate = state.Font;
                Size measured = TextRenderer.MeasureText(check.Text, candidate, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.SingleLine | TextFormatFlags.NoPadding);
                while (measured.Width + 26 > available && candidate.SizeInPoints > 7F)
                {
                    candidate = new Font(state.Font.FontFamily, Math.Max(7F, candidate.SizeInPoints - 0.5F), state.Font.Style, GraphicsUnit.Point);
                    measured = TextRenderer.MeasureText(check.Text, candidate, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.SingleLine | TextFormatFlags.NoPadding);
                }
                check.Font = candidate;
                if (measured.Width + 26 > available)
                {
                    check.AutoSize = false;
                    check.Size = new Size(available, Math.Max(check.Height, candidate.Height * 2 + 4));
                }
                else check.AutoSize = state.AutoSize;
                return;
            }
            Label label = control as Label;
            if (label == null) return;
            if (state.Font.SizeInPoints >= 15F) { if (!object.ReferenceEquals(label.Font, state.Font)) label.Font = state.Font; label.AutoSize = state.AutoSize; return; }
            if (!_english)
            {
                if (!object.ReferenceEquals(label.Font, state.Font)) label.Font = state.Font;
                label.AutoSize = state.AutoSize;
                return;
            }
            if (label.Parent == null || label.Parent.ClientSize.Width < 100) return;
            int maxWidth = Math.Max(80, label.Parent.ClientSize.Width - label.Left - 18);
            foreach (Control sibling in label.Parent.Controls)
            {
                if (sibling == label || !sibling.Visible) continue;
                if (sibling.Left > label.Left && sibling.Top < label.Bottom && sibling.Bottom > label.Top) maxWidth = Math.Max(80, Math.Min(maxWidth, sibling.Left - label.Left - 10));
            }
            if (!state.AutoSize) maxWidth = Math.Min(maxWidth, label.Width);
            Font fitted = state.Font;
            Size size = TextRenderer.MeasureText(label.Text, fitted, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.SingleLine | TextFormatFlags.NoPadding);
            while (size.Width > maxWidth && fitted.SizeInPoints > 7.5F)
            {
                fitted = new Font(state.Font.FontFamily, Math.Max(7.5F, fitted.SizeInPoints - 0.5F), fitted.Style, GraphicsUnit.Point);
                size = TextRenderer.MeasureText(label.Text, fitted, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.SingleLine | TextFormatFlags.NoPadding);
            }
            if (!object.ReferenceEquals(label.Font, fitted)) label.Font = fitted;
            if (size.Width > maxWidth)
            {
                label.AutoSize = false;
                int maxHeight = Math.Max(fitted.Height + 2, label.Parent.ClientSize.Height - label.Top - 4);
                foreach (Control sibling in label.Parent.Controls) if (sibling != label && sibling.Visible && sibling.Top >= label.Bottom && sibling.Left < label.Left + maxWidth && sibling.Right > label.Left) maxHeight = Math.Min(maxHeight, Math.Max(fitted.Height + 2, sibling.Top - label.Top - 4));
                Size needed = TextRenderer.MeasureText(label.Text, fitted, new Size(maxWidth, int.MaxValue), TextFormatFlags.WordBreak);
                label.Size = new Size(maxWidth, Math.Min(maxHeight, needed.Height + 4));
            }
            else if (state.AutoSize) label.AutoSize = true;
        }
    }

    internal static class Ui
    {
