        private static ModernButton AddButton(FlowLayoutPanel parent, string text, int width, Action click)
        {
            ModernButton button = new ModernButton
            {
                Text = text,
                Size = new Size(width, 38),
                Margin = new Padding(0, 0, 10, 0),
                BaseColor = Ui.CardAlt
            };
            button.Click += delegate { click(); };
            parent.Controls.Add(button);
            return button;
        }

        private void UpdateEditor()
        {
            StepKind kind = (StepKind)_action.SelectedItem;
            bool isText = kind == StepKind.StopCode || kind == StepKind.FailedOperation;
            _editorFields.Visible = kind != StepKind.ChangeText;
            _changeTextEditor.Visible = kind == StepKind.ChangeText;
            _text.Visible = _inputLabel.Visible = isText;
            _inputLabel.Text = kind == StepKind.StopCode ? "要显示的终止代码" : "要显示的文件名或说明";
            _background.Visible = kind == StepKind.Background;
            _textBackground.Visible = _foreground.Visible = kind == StepKind.TextColors;
            _qrStatus.Visible = kind == StepKind.Qr;
            if (_qrEditorFull != null)
            {
                _qrEditorFull.Visible = kind == StepKind.Qr;
                if (kind == StepKind.Qr)
                {
                    try { _qrEditorFull.LoadRectangleDescription(); }
                    catch { }
                }
            }
            _qrStatus.Text = _qr == null ? "在下方画板绘制，添加步骤时将自动使用当前画板内容。" : "已记录 " + _qr.Dimensions + "，添加步骤时将自动使用当前画板内容。";
        }

        private void UpdateButtons()
        {
            int index = _steps.SelectedIndex;
            StepKind kind = (StepKind)_action.SelectedItem;
            bool hasRainbow = IsRainbowStep(_steps.Items.Count - 1);
            _add.Enabled = !hasRainbow;
            _add.BaseColor = hasRainbow ? SystemColors.Control : Ui.Accent;
            _up.Enabled = CanMoveStep(index, index - 1);
            _down.Enabled = CanMoveStep(index, index + 1);
            _remove.Enabled = index >= 0;
            _replace.Enabled = CanReplaceStep(index, kind);
            _previewButton.Enabled = _register.Enabled = _steps.Items.Count > 0;
            _rainbowStatus.Text = hasRainbow ? "请先删除彩虹蓝屏，再添加步骤。" : "彩虹蓝屏固定为最后一步。";
            _rainbowStatus.Visible = hasRainbow || kind == StepKind.Rainbow;
        }

        private bool IsRainbowStep(int index)
        {
            return index >= 0 && ((CallbackStep)_steps.Items[index]).Kind == StepKind.Rainbow;
        }

        private bool CanMoveStep(int index, int target)
        {
            return index >= 0 && target >= 0 && target < _steps.Items.Count && !IsRainbowStep(index) && !IsRainbowStep(target);
        }

        private bool CanReplaceStep(int index, StepKind kind)
        {
            return index >= 0 && !IsRainbowStep(index) && (kind != StepKind.Rainbow || index == _steps.Items.Count - 1);
        }

        private void LoadSelectedStep()
        {
            CallbackStep step = _steps.SelectedItem as CallbackStep;
            if (step != null)
            {
                _action.SelectedItem = step.Kind;
                _text.Text = step.Text ?? string.Empty;
                _qr = step.Qr;
                if (step.Kind == StepKind.Background) _background.Value = step.FirstColor;
                if (step.Kind == StepKind.TextColors)
                {
                    _textBackground.Value = step.FirstColor;
                    _foreground.Value = step.SecondColor;
                }
                if (step.Kind == StepKind.ChangeText) _changeTextEditor.LoadTexts(step.ChangeTextTexts, step.ChangeTextMode, step.ChangeTextTargetCount);
                UpdateEditor();
            }
            UpdateButtons();
        }

        private void EnsureQrAvailable()
        {
            if (_qrEditor == null || (!Program.IsQrCustomizationSupported() && !Program.ForceWindows10BlueScreenEffect)) throw new InvalidOperationException("请先在「特效与触发」切换到支持二维码的蓝屏样式。");
        }

        private void CaptureQr()
        {
            QrConfiguration configuration = _qrEditorFull.CaptureSilently();
            if (configuration == null) return;
            _qr = configuration;
        }

        private void SaveStep(bool replace)
        {
            RunAction(delegate
            {
                int index = _steps.SelectedIndex;
                StepKind kind = (StepKind)_action.SelectedItem;
                if (replace ? !CanReplaceStep(index, kind) : IsRainbowStep(_steps.Items.Count - 1)) return;
                CallbackStep step = new CallbackStep { Kind = kind };
                switch (step.Kind)
                {
                    case StepKind.StopCode:
                    case StepKind.FailedOperation:
                        step.Text = MainForm.ValidateProtocolText(_text.Text, true).Trim();
                        if (step.Text.Length == 0) throw new InvalidOperationException("请填写要显示的文本。");
                        byte[] encoded = Encoding.Default.GetBytes(step.Text);
                        if (Array.IndexOf(encoded, (byte)'"') >= 0 || Array.IndexOf(encoded, (byte)0) >= 0) throw new InvalidOperationException("文本转为驱动编码后包含双引号或空字符。");
                        break;
                    case StepKind.Background:
                        step.FirstColor = _background.Value;
                        break;
                    case StepKind.TextColors:
                        step.FirstColor = _textBackground.Value;
                        step.SecondColor = _foreground.Value;
                        break;
                    case StepKind.Qr:
                        EnsureQrAvailable();
                        CaptureQr();
                        if (_qr == null) throw new InvalidOperationException("二维码画板无效或尚未读取到驱动尺寸。");
                        step.Qr = _qr;
                        break;
                    case StepKind.ChangeText:
                        step.ChangeTextTexts = _changeTextEditor.GetPreviewTexts();
                        step.ChangeTextMode = _changeTextEditor.SelectedMode;
                        step.ChangeTextTargetCount = _changeTextEditor.RenderCount;
                        step.ChangeTextCommand = ChangeTextPage.BuildProtocolCommand(step.ChangeTextTexts, step.ChangeTextMode, Program.ForceWindows10BlueScreenEffect, _failedOperationSet(), step.ChangeTextTargetCount);
                        break;
                }
                if (replace) _steps.Items[index] = step;
                else index = _steps.Items.Add(step);
                _steps.SelectedIndex = index;
                UpdateButtons();
            });
        }

        private void MoveStep(int offset)
        {
            int index = _steps.SelectedIndex;
            int target = index + offset;
            if (!CanMoveStep(index, target)) return;
            object step = _steps.Items[index];
            _steps.Items.RemoveAt(index);
            _steps.Items.Insert(target, step);
            _steps.SelectedIndex = target;
            UpdateButtons();
        }

        private void RemoveStep()
        {
            int index = _steps.SelectedIndex;
            if (index < 0) return;
            _steps.Items.RemoveAt(index);
            _steps.SelectedIndex = Math.Min(index, _steps.Items.Count - 1);
            UpdateButtons();
        }

        private void Preview()
        {
            PreviewSnapshot snapshot = PreviewSnapshot.CreateDefault(_windows7);
            foreach (CallbackStep step in _steps.Items) step.ApplyToPreview(snapshot);
            _preview(snapshot, "蓝屏回调外观预览");
        }

        private static string EscapeRcCommand(string value)
        {
            return value.Replace("\\", "\\\\").Replace("\"", "\\\"");
        }

        private void Register()
        {
            if (_steps.Items.Count == 0) return;
            StringBuilder command = new StringBuilder("RC");
            foreach (CallbackStep step in _steps.Items)
            {
                if (step.Kind == StepKind.Qr)
                {
                    EnsureQrAvailable();
                    if (!_qrEditor.MatchesCurrentDimensions(step.Qr) && (_qrEditorFull == null || !_qrEditorFull.MatchesCurrentDimensions(step.Qr))) throw new InvalidOperationException("二维码尺寸已变更。请重新读取画板图像并更新相应步骤。");
                }
                command.Append(" \"").Append(EscapeRcCommand(step.BuildCommand())).Append('"');
            }
            _send(command.ToString());
        }

        private void RunAction(Action action)
        {
            try { action(); }
            catch (Exception ex)
            {
                LanguageManager.Show(FindForm(), ex.Message, "蓝屏回调设置", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        }

        private sealed class CallbackStep
        {
            public StepKind Kind;
            public string Text;
            public uint FirstColor;
            public uint SecondColor;
            public QrConfiguration Qr;
            public List<string> ChangeTextTexts;
            public int ChangeTextMode;
            public int ChangeTextTargetCount;
            public string ChangeTextCommand;

            public string BuildCommand()
            {
                switch (Kind)
                {
                    case StepKind.StopCode: return "SP " + Text;
                    case StepKind.FailedOperation: return "WF " + Text;
                    case StepKind.Background: return "CR " + FirstColor.ToString(CultureInfo.InvariantCulture);
                    case StepKind.TextColors: return "CC " + FirstColor.ToString(CultureInfo.InvariantCulture) + " " + SecondColor.ToString(CultureInfo.InvariantCulture);
                    case StepKind.Qr: return Qr.BuildCommand();
                    case StepKind.Rainbow: return "RD";
                    case StepKind.ChangeText: return ChangeTextCommand;
                    default: throw new InvalidOperationException("未知的蓝屏回调步骤。");
                }
            }

            public void ApplyToPreview(PreviewSnapshot snapshot)
            {
                switch (Kind)
                {
                    case StepKind.StopCode: snapshot.StopCode = Text; break;
                    case StepKind.FailedOperation: snapshot.FailedOperation = Text; break;
                    case StepKind.Background: snapshot.Background = Color.FromArgb(unchecked((int)FirstColor)); break;
                    case StepKind.TextColors: snapshot.TextBackground = Color.FromArgb(unchecked((int)FirstColor)); snapshot.Foreground = Color.FromArgb(unchecked((int)SecondColor)); break;
                    case StepKind.Qr: Qr.ApplyToPreview(snapshot); break;
                    case StepKind.Rainbow: snapshot.Rainbow = true; break;
                    case StepKind.ChangeText:
                        if (ChangeTextTexts != null)
                        {
                            snapshot.ReplacementTexts.AddRange(ChangeTextTexts);
                            snapshot.SkipPercent = (ChangeTextMode & 1) != 0;
                            snapshot.ChangeTextFillMode = ((ChangeTextMode & 6) == 6) ? 0 : (ChangeTextMode & 6);
                        }
                        break;
                }
            }

            public override string ToString()
            {
                string detail;
                switch (Kind)
                {
                    case StepKind.Background: detail = FirstColor.ToString("X8", CultureInfo.InvariantCulture); break;
                    case StepKind.TextColors: detail = FirstColor.ToString("X8", CultureInfo.InvariantCulture) + " / " + SecondColor.ToString("X8", CultureInfo.InvariantCulture); break;
                    case StepKind.Qr: detail = Qr.Dimensions; break;
                    case StepKind.Rainbow: return LanguageManager.T(StepNames[(int)Kind]);
                    case StepKind.ChangeText: detail = (ChangeTextTexts == null ? 0 : ChangeTextTexts.Count).ToString(CultureInfo.InvariantCulture) + LanguageManager.T(" 条文本"); break;
                    default: detail = Text; break;
                }
                return LanguageManager.T(StepNames[(int)Kind]) + "  " + detail;
            }
        }
    }

    internal enum PreviewKind
    {
        Full,
        Windows7StopCode,
        Windows7FailedOperation,
        Windows7Colors,
        Windows7DisplayString,
        Windows7Rainbow,
        ModernStopCode,
        ModernBackground,
        ModernTextColors,
        ModernChangeText,
        ModernDisplayStrings,
        ModernRainbow
    }

    internal static class BsodQrPattern
    {
        private static readonly string[] Rows =
        {
            "#######.##.#.#.##.#######",
            "#.....#.###.....#.#.....#",
            "#.###.#.##....#...#.###.#",
            "#.###.#.#..#.##.#.#.###.#",
            "#.###.#....#.#.##.#.###.#",
            "#.....#.#.#.#.#...#.....#",
            "#######.#.#.#.#.#.#######",
            ".........###..##.........",
            "##..###..##...#....#.####",
            "...#.#..#..#..####..##.#.",
            "#.########.######..####..",
            "##...#.###..#.....##..##.",
            "#.#..##....##..#.##..####",
            "##.#...##..#.#####..#..#.",
            "......#.####.#.#...####..",
            "..###...#.###.###.###.##.",
            "##...####.#....########..",
            "........##.#..#.#...#....",
            "#######..#.####.#.#.#....",
            "#.....#.###...#.#...####.",
            "#.###.#.##......#######.#",
            "#.###.#...##..###.##..#..",
            "#.###.#...###.#.###..#.#.",
            "#.....#.#...#.#...######.",
            "#######.##.##.##......###"
        };

        public static readonly Color CodeColor = Color.FromArgb(0, 120, 215);

        public static void Draw(Graphics graphics, RectangleF bounds)
        {
            Draw(graphics, bounds, CodeColor);
        }

        public static void Draw(Graphics graphics, RectangleF bounds, Color codeColor)
        {
            float side = Math.Min(bounds.Width, bounds.Height);
            float left = bounds.Left + (bounds.Width - side) / 2F;
            float top = bounds.Top + (bounds.Height - side) / 2F;
            using (Brush white = new SolidBrush(Color.White)) graphics.FillRectangle(white, left, top, side, side);
            float quiet = side * (24F / 284F);
            float codeSize = side - (quiet * 2F);
            float module = codeSize / 25F;
            using (Brush code = new SolidBrush(Color.FromArgb(255, codeColor.R, codeColor.G, codeColor.B)))
            {
                for (int row = 0; row < Rows.Length; row++)
                {
                    for (int column = 0; column < Rows[row].Length; column++)
                    {
                        if (Rows[row][column] != '#') continue;
                        float x0 = left + quiet + (column * module);
                        float y0 = top + quiet + (row * module);
                        float x1 = left + quiet + ((column + 1) * module);
                        float y1 = top + quiet + ((row + 1) * module);
                        graphics.FillRectangle(code, x0, y0, Math.Max(1F, x1 - x0), Math.Max(1F, y1 - y0));
                    }
                }
            }
        }
    }

    internal sealed class PreviewSnapshot
    {
        public PreviewKind Kind;
        public bool Windows7;
        public bool Windows8;
        public bool Windows11New;
        public bool SkipPercent;
        public int ChangeTextFillMode;
        public Color Background;
        public Color Foreground;
        public Color TextBackground;
        public string StopCode;
        public string FailedOperation;
        public bool Rainbow;
        public int QrWidth;
        public int QrLength;
        public uint[] QrPixels;
        public readonly List<string> ReplacementTexts = new List<string>();
        public readonly List<PreviewTextItem> DisplayItems = new List<PreviewTextItem>();
        public readonly List<PreviewImageItem> DisplayImages = new List<PreviewImageItem>();

        public static PreviewSnapshot CreateDefault(bool windows7)
        {
            bool windows8 = !windows7 && Program.IsWindows8();
            Color modernBlue = windows8 ? Color.FromArgb(32, 103, 178) : Color.FromArgb(0, 120, 212);
            bool windows11New = !windows7 && Program.IsWindows11NewBlueScreen() && !Program.ForceWindows10BlueScreenEffect;
            return new PreviewSnapshot
            {
                Kind = PreviewKind.Full,
                Windows7 = windows7,
                Windows8 = windows8,
                Windows11New = windows11New,
                Background = windows7 ? Color.FromArgb(0, 0, 128) : (windows11New ? Color.Black : modernBlue),
                Foreground = Color.White,
                TextBackground = windows7 ? Color.Transparent : (windows11New ? Color.Black : modernBlue),
                StopCode = null
            };
        }
    }

    internal sealed class PreviewTextItem
    {
        public string Text;
        public uint TextSize;
        public Color TextBackground;
        public Color TextForeground;
        public Color ScreenBackground;
        public uint X;
        public uint Y;
        public bool ClearScreen;
        public bool VgaText;
        public bool Vga80x25;
        public int VgaBackground;
        public int VgaForeground;
        public bool Blink;
        public bool Rainbow;
    }

    internal sealed class PreviewImageItem
    {
        public uint[] Pixels;
        public int Width;
        public int Height;
        public uint X;
        public uint Y;
        public Color ScreenBackground;
        public bool ClearScreen;
    }

    internal sealed class PreviewForm : Form
    {
        public PreviewForm(PreviewSnapshot snapshot, string title)
        {
            Text = title + " — 预览效果可能与实际效果不同 (按下Esc 退出)";
            StartPosition = FormStartPosition.CenterParent;
            FormBorderStyle = FormBorderStyle.FixedSingle;
            WindowState = FormWindowState.Maximized;
            BackColor = Color.Black;
            ShowIcon = false;
            MaximizeBox = false;
            MinimizeBox = false;
            KeyPreview = true;
            KeyDown += delegate (object sender, KeyEventArgs e)
            {
                if (e.KeyCode == Keys.Escape) Close();
            };
            Controls.Add(new PreviewCanvas(snapshot) { Dock = DockStyle.Fill });
            LanguageManager.Attach(this);
        }
    }

    internal sealed class PreviewCanvas : Control
    {
        private static readonly Color ModernBlue = Color.FromArgb(0, 120, 212);
        private static readonly Color Windows8Blue = Color.FromArgb(32, 103, 178);
        private readonly PreviewSnapshot _snapshot;
        private readonly Bitmap _qrBitmap;
        private readonly Timer _timer;
        private readonly Stopwatch _animationClock;
        private double _hue;
        private int _frame;

        public PreviewCanvas(PreviewSnapshot snapshot)
        {
            _snapshot = snapshot;
            _qrBitmap = BuildQrBitmap(snapshot);
            DoubleBuffered = true;
            BackColor = snapshot.Background;
            if (snapshot.Rainbow || IsRainbowKind(snapshot.Kind) || HasAnimatedText(snapshot.DisplayItems))
            {
                _animationClock = Stopwatch.StartNew();
                _timer = new Timer { Interval = 16 };
                _timer.Tick += delegate
                {
                    double elapsedSeconds = _animationClock.Elapsed.TotalSeconds;
                    _hue = (elapsedSeconds * 100.0) % 360.0;
                    _frame = (int)(elapsedSeconds * (1000.0 / 120.0));
                    Invalidate();
                };
                _timer.Start();
            }
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing)
            {
                if (_timer != null) _timer.Dispose();
                if (_qrBitmap != null) _qrBitmap.Dispose();
            }
            base.Dispose(disposing);
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            e.Graphics.SmoothingMode = SmoothingMode.None;
            e.Graphics.TextRenderingHint = System.Drawing.Text.TextRenderingHint.SingleBitPerPixelGridFit;
            if (_snapshot.Windows7) DrawWindows7(e.Graphics);
            else DrawModern(e.Graphics);
        }

        private void DrawWindows7(Graphics graphics)
        {
            bool displayOnly = _snapshot.Kind == PreviewKind.Windows7DisplayString || (_snapshot.Kind == PreviewKind.Full && _snapshot.DisplayItems.Count > 0);
            if (displayOnly)
            {
                DrawWindows7DisplayString(graphics);
                return;
            }
            if (_snapshot.Kind == PreviewKind.Windows7FailedOperation)
            {
                Fill(graphics, Color.FromArgb(0, 0, 128));
                DrawWindows7FailedOperation(graphics, Opaque(_snapshot.Foreground));
                return;
            }
            bool rainbow = _snapshot.Kind == PreviewKind.Windows7Rainbow || _snapshot.Rainbow;
            Color background = rainbow ? FromHsv(_hue, 1.0, 1.0) : Opaque(_snapshot.Background);
            Color foreground = rainbow ? FromHsv((_hue + 180.0) % 360.0, 1.0, 0.15) : Opaque(_snapshot.Foreground);
            Fill(graphics, background);
            DrawWindows7CrashText(graphics, foreground);
        }

        private void DrawWindows7CrashText(Graphics graphics, Color foreground)
        {
            float sx = ClientSize.Width / 800F;
            float sy = ClientSize.Height / 600F;
            GraphicsState state = graphics.Save();
            graphics.ScaleTransform(sx, sy);
            using (Font font = new Font("Lucida Console", 13F, FontStyle.Regular, GraphicsUnit.Pixel))
            using (Brush brush = new SolidBrush(foreground))
            {
                DrawWindows7Introduction(graphics, font, brush, 18F, 16F);
                DrawWindows7Troubleshooting(graphics, font, brush, 96F, 16F);
                bool customStop = _snapshot.Kind == PreviewKind.Windows7StopCode || (_snapshot.Kind == PreviewKind.Full && !string.IsNullOrEmpty(_snapshot.StopCode));
                if (customStop)
                {
                    DrawClassicLine(graphics, font, brush, _snapshot.StopCode ?? "CUSTOM_STOP_CODE", 320);
                    if (!string.IsNullOrEmpty(_snapshot.FailedOperation)) DrawClassicLine(graphics, font, brush, _snapshot.FailedOperation, 336);
                    DrawClassicLine(graphics, font, brush, "Collecting data for crash dump ...", 352);
                    DrawClassicLine(graphics, font, brush, "Initializing disk for crash dump ...", 368);
                }
                else
                {
                    DrawClassicLine(graphics, font, brush, "Technical information:", 320);
                    DrawClassicLine(graphics, font, brush, "*** STOP: 0x00114514 (0x0000000000000000,0x0000000000000000,", 352);
                    DrawClassicLine(graphics, font, brush, "0x0000000000000000,0x0000000000000000)", 368);
                    if (!string.IsNullOrEmpty(_snapshot.FailedOperation)) DrawClassicLine(graphics, font, brush, _snapshot.FailedOperation, 400);
                    DrawClassicLine(graphics, font, brush, "Collecting data for crash dump ...", 432);
                    DrawClassicLine(graphics, font, brush, "Initializing disk for crash dump ...", 448);
                }
            }
            graphics.Restore(state);
        }

        private void DrawWindows7FailedOperation(Graphics graphics, Color foreground)
        {
            const int columns = 80;
            const string stopLine = "*** STOP: 0x00114514 (0x0000000000000000,0x0000000000000000,0x0000000000000000,0x0000000000000000)";
            GraphicsState state = graphics.Save();
            graphics.TextRenderingHint = System.Drawing.Text.TextRenderingHint.SingleBitPerPixelGridFit;
            graphics.ScaleTransform(ClientSize.Width / 800F, ClientSize.Height / 600F);
            using (Font font = new Font("Lucida Console", 13F, FontStyle.Regular, GraphicsUnit.Pixel))
            using (Brush brush = new SolidBrush(foreground))
            using (StringFormat filenameFormat = StringFormat.GenericTypographic)
            {
                float textWidth = graphics.MeasureString(new string('0', columns), font, PointF.Empty, filenameFormat).Width;
                float cellWidth = textWidth / columns;
                float textHeight = font.GetHeight(graphics);
                filenameFormat.FormatFlags = (filenameFormat.FormatFlags | StringFormatFlags.NoWrap) & ~StringFormatFlags.LineLimit;
                filenameFormat.Trimming = StringTrimming.EllipsisCharacter;
                DrawWindows7Introduction(graphics, font, brush, 18F, 16F);
                DrawWindows7Troubleshooting(graphics, font, brush, 96F, 16F);
                DrawClassicLine(graphics, font, brush, "Technical information:", 320F);
                DrawClassicLine(graphics, font, brush, stopLine.Substring(0, columns), 352F);
                DrawClassicLine(graphics, font, brush, stopLine.Substring(columns), 368F);
                DrawClassicLine(graphics, font, brush, "Collecting data for crash dump ...", 432F);
                DrawClassicLine(graphics, font, brush, "Initializing disk for crash dump ...", 448F);
                string filename = _snapshot.FailedOperation;
                if (!string.IsNullOrEmpty(filename))
                {
                    graphics.DrawString(filename, font, brush, new RectangleF(cellWidth, 54F, textWidth - cellWidth, textHeight), filenameFormat);
                    graphics.DrawString(filename, font, brush, new RectangleF(0F, 400F, textWidth, textHeight), filenameFormat);
                }
            }
            graphics.Restore(state);
        }

        private static void DrawWindows7Introduction(Graphics graphics, Font font, Brush brush, float top, float lineHeight)
        {
            DrawClassicLine(graphics, font, brush, "A problem has been detected and Windows has been shut down to prevent damage", top);
            DrawClassicLine(graphics, font, brush, "to your computer.", top + lineHeight);
        }

        private static void DrawWindows7Troubleshooting(Graphics graphics, Font font, Brush brush, float top, float lineHeight)
        {
            DrawClassicLine(graphics, font, brush, "If this is the first time you've seen this Stop error screen,", top);
            DrawClassicLine(graphics, font, brush, "restart your computer. If this screen appears again, follow", top + lineHeight);
            DrawClassicLine(graphics, font, brush, "these steps:", top + 2F * lineHeight);
            DrawClassicLine(graphics, font, brush, "Check to make sure any new hardware or software is properly installed.", top + 4F * lineHeight);
            DrawClassicLine(graphics, font, brush, "If this is a new installation, ask your hardware or software manufacturer", top + 5F * lineHeight);
            DrawClassicLine(graphics, font, brush, "for any Windows updates you might need.", top + 6F * lineHeight);
            DrawClassicLine(graphics, font, brush, "If problems continue, disable or remove any newly installed hardware", top + 8F * lineHeight);
            DrawClassicLine(graphics, font, brush, "or software. Disable BIOS memory options such as caching or shadowing.", top + 9F * lineHeight);
            DrawClassicLine(graphics, font, brush, "If you need to use Safe Mode to remove or disable components, restart", top + 10F * lineHeight);
            DrawClassicLine(graphics, font, brush, "your computer, press F8 to select Advanced Startup Options, and then", top + 11F * lineHeight);
            DrawClassicLine(graphics, font, brush, "select Safe Mode.", top + 12F * lineHeight);
        }

        private static void DrawClassicLine(Graphics graphics, Font font, Brush brush, string text, float y)
        {
            graphics.DrawString(text, font, brush, 0F, y, StringFormat.GenericTypographic);
        }

        private void DrawWindows7DisplayString(Graphics graphics)
        {
            PreviewTextItem item = _snapshot.DisplayItems.Count > 0 ? _snapshot.DisplayItems[0] : new PreviewTextItem
            {
                Text = "Your costom text",
                Vga80x25 = true,
                VgaBackground = 0x7,
                VgaForeground = 0x0
            };
            int backgroundIndex = item.Blink ? item.VgaBackground & 0x07 : item.VgaBackground;
            Color background = item.Rainbow ? VgaColor((_frame / 2) & 0x0F) : VgaColor(backgroundIndex);
            Color foreground = item.Rainbow ? VgaColor(0x0F - ((_frame / 2) & 0x0F)) : VgaColor(item.VgaForeground);
            Fill(graphics, background);
            if (item.Blink && ((_frame / 4) & 1) != 0) return;
            int rows = item.Vga80x25 ? 25 : 50;
            float cellHeight = Math.Max(8F, ClientSize.Height / (float)rows);
            using (Font font = new Font("Terminal", cellHeight, FontStyle.Bold, GraphicsUnit.Pixel))
            using (Brush brush = new SolidBrush(foreground))
            {
                graphics.DrawString(item.Text ?? string.Empty, font, brush, 0F, 0F, StringFormat.GenericTypographic);
            }
        }

        private void DrawModern(Graphics graphics)
        {
            if (_snapshot.Kind == PreviewKind.ModernDisplayStrings)
            {
                Fill(graphics, Color.Black);
                DrawModernDisplayStrings(graphics);
                return;
            }
            if (_snapshot.Windows8)
            {
                DrawWindows8(graphics);
                return;
            }
            if (_snapshot.Windows11New)
            {
                DrawWindows11(graphics);
                return;
            }
            if (_snapshot.Kind == PreviewKind.ModernChangeText)
            {
                Fill(graphics, ModernBlue);
                DrawModernChangeText(graphics);
                return;
            }
            bool rainbow = _snapshot.Kind == PreviewKind.ModernRainbow || _snapshot.Rainbow;
            Color background = rainbow ? FromHsv(_hue, 1.0, 1.0) : Opaque(_snapshot.Background);
            Color foreground = rainbow ? Color.White : Opaque(_snapshot.Foreground);
            Color glyphBackground;
            if (_snapshot.Kind == PreviewKind.ModernBackground || _snapshot.Kind == PreviewKind.ModernStopCode) glyphBackground = ModernBlue;
            else if (rainbow) glyphBackground = background;
            else glyphBackground = Opaque(_snapshot.TextBackground);
            Fill(graphics, background);
            if (_snapshot.Kind == PreviewKind.Full && _snapshot.ReplacementTexts.Count > 0) DrawModernChangeText(graphics, foreground, glyphBackground);
            else DrawModernCrashText(graphics, foreground, glyphBackground, rainbow);
        }

        private void DrawWindows8(Graphics graphics)
        {
            bool rainbow = _snapshot.Kind == PreviewKind.ModernRainbow || _snapshot.Rainbow;
            Color background = rainbow ? FromHsv(_hue, 1.0, 1.0) : Opaque(_snapshot.Background);
            Color foreground = rainbow ? Color.White : Opaque(_snapshot.Foreground);
            Color glyphBackground;
            if (_snapshot.Kind == PreviewKind.ModernBackground || _snapshot.Kind == PreviewKind.ModernStopCode) glyphBackground = Windows8Blue;
            else if (rainbow) glyphBackground = background;
            else glyphBackground = Opaque(_snapshot.TextBackground);
            Fill(graphics, background);
            if ((_snapshot.Kind == PreviewKind.ModernChangeText || _snapshot.Kind == PreviewKind.Full) && _snapshot.ReplacementTexts.Count > 0) DrawWindows8ChangeText(graphics, foreground, glyphBackground);
            else DrawWindows8CrashText(graphics, foreground, glyphBackground, rainbow);
