        private void DrawWindows11ChangeText(Graphics graphics, Font body, Font progress, Font small, Color foreground, Color glyphBackground, float sy)
        {
            List<string> values = PadPreviewValues(_snapshot.ReplacementTexts, 4);
            string mainText = ValueAtOrRepeatLast(values, 0, "你的设备遇到问题，需要重启。");
            string stopCode = string.IsNullOrEmpty(_snapshot.StopCode) ? "APC_INDEX_MISMATCH" : _snapshot.StopCode;
            string bottomText = ValueAtOrRepeatLast(values, 1, "终止代码: " + stopCode + " (0x1)");
            bool failed = !string.IsNullOrEmpty(_snapshot.FailedOperation);
            string progressText = failed ? ValueAtOrRepeatLast(values, 3, "0% 完成") : ValueAtOrRepeatLast(values, 2, "0% 完成");
            DrawCenteredTextBlock(graphics, mainText, body, foreground, glyphBackground, ClientSize.Width / 2F, 635F * sy);
            DrawCenteredTextBlock(graphics, progressText, progress, foreground, glyphBackground, ClientSize.Width / 2F, 755F * sy);
            DrawCenteredTextBlock(graphics, bottomText, small, foreground, glyphBackground, ClientSize.Width / 2F, (failed ? 1415F : 1460F) * sy);
            if (failed) DrawCenteredTextBlock(graphics, ValueAtOrRepeatLast(values, 2, "失败的操作: " + _snapshot.FailedOperation), small, foreground, glyphBackground, ClientSize.Width / 2F, 1460F * sy);
        }

        private void DrawModernDisplayStrings(Graphics graphics)
        {
            float scaleX = ClientSize.Width / 1152F;
            float scaleY = ClientSize.Height / 864F;
            float fontScale = Math.Min(scaleX, scaleY);
            foreach (PreviewTextItem item in _snapshot.DisplayItems)
            {
                if (item.ClearScreen) Fill(graphics, Opaque(item.ScreenBackground));
                float fontSize = Math.Max(8F, item.TextSize * fontScale);
                float x = item.X * scaleX;
                float y = item.Y * scaleY;
                Color foreground = item.Rainbow ? Color.White : Opaque(item.TextForeground);
                Color background = item.Rainbow ? FromHsv(_hue, 1.0, 1.0) : Opaque(item.TextBackground);
                using (Font font = new Font("Segoe UI", fontSize, FontStyle.Regular, GraphicsUnit.Pixel))
                {

                    DrawTextBlock(graphics, item.Text ?? string.Empty, font, foreground, background, x, y, false);
                }
            }
            foreach (PreviewImageItem item in _snapshot.DisplayImages)
            {
                if (item.ClearScreen) Fill(graphics, Opaque(item.ScreenBackground));
                if (item.Pixels == null || item.Width <= 0 || item.Height <= 0 || (long)item.Width * item.Height != item.Pixels.Length) continue;
                using (Bitmap bitmap = new Bitmap(item.Width, item.Height))
                {
                    int pixelIndex = 0;
                    for (int y = 0; y < item.Height; y++) for (int x = 0; x < item.Width; x++) bitmap.SetPixel(x, y, Color.FromArgb(unchecked((int)item.Pixels[pixelIndex++])));
                    InterpolationMode previous = graphics.InterpolationMode;
                    PixelOffsetMode previousOffset = graphics.PixelOffsetMode;
                    graphics.InterpolationMode = InterpolationMode.NearestNeighbor;
                    graphics.PixelOffsetMode = PixelOffsetMode.Half;
                    graphics.DrawImage(bitmap, new RectangleF(item.X * scaleX, item.Y * scaleY, Math.Max(1F, item.Width * scaleX), Math.Max(1F, item.Height * scaleY)), new RectangleF(0, 0, item.Width, item.Height), GraphicsUnit.Pixel);
                    graphics.InterpolationMode = previous;
                    graphics.PixelOffsetMode = previousOffset;
                }
            }
        }

        private void DrawQrCode(Graphics graphics, float x, float y, float size)
        {
            RectangleF area = new RectangleF(x, y, size, size);
            if (_qrBitmap == null)
            {
                BsodQrPattern.Draw(graphics, area);
                return;
            }
            using (Brush white = new SolidBrush(Color.White)) graphics.FillRectangle(white, area);
            float scale = Math.Min(size / _qrBitmap.Width, size / _qrBitmap.Height);
            float width = Math.Max(1F, _qrBitmap.Width * scale);
            float height = Math.Max(1F, _qrBitmap.Height * scale);
            RectangleF destination = new RectangleF(x + (size - width) / 2F, y + (size - height) / 2F, width, height);
            InterpolationMode previous = graphics.InterpolationMode;
            PixelOffsetMode previousOffset = graphics.PixelOffsetMode;
            graphics.InterpolationMode = InterpolationMode.NearestNeighbor;
            graphics.PixelOffsetMode = PixelOffsetMode.Half;
            graphics.DrawImage(_qrBitmap, destination, new RectangleF(0, 0, _qrBitmap.Width, _qrBitmap.Height), GraphicsUnit.Pixel);
            graphics.InterpolationMode = previous;
            graphics.PixelOffsetMode = previousOffset;
        }

        private static Bitmap BuildQrBitmap(PreviewSnapshot snapshot)
        {
            if (snapshot == null || snapshot.QrPixels == null || snapshot.QrWidth <= 0 || snapshot.QrLength <= 0) return null;
            if ((long)snapshot.QrWidth * snapshot.QrLength != snapshot.QrPixels.Length) return null;
            Bitmap bitmap = new Bitmap(snapshot.QrLength, snapshot.QrWidth);
            int index = 0;
            for (int row = 0; row < snapshot.QrWidth; row++) for (int column = 0; column < snapshot.QrLength; column++) bitmap.SetPixel(column, row, Color.FromArgb(unchecked((int)snapshot.QrPixels[index++])));
            return bitmap;
        }

        private static Font FitPreviewFont(Graphics graphics, string text, Font original, float availableWidth)
        {
            if (!LanguageManager.IsEnglish || availableWidth <= 0) return original;
            SizeF measured = graphics.MeasureString(text, original, PointF.Empty, StringFormat.GenericTypographic);
            if (measured.Width <= availableWidth) return original;
            float size = Math.Max(8F, original.Size * availableWidth / Math.Max(1F, measured.Width));
            return new Font(original.FontFamily, size, original.Style, original.Unit);
        }

        private static void DrawTextBlock(Graphics graphics, string text, Font font, Color foreground, Color background, float x, float y, bool localize = true)
        {
            string shown = localize ? LanguageManager.T(text ?? string.Empty) : (text ?? string.Empty);
            float available = graphics.VisibleClipBounds.Right - x - 12F;
            Font displayedFont = localize ? FitPreviewFont(graphics, shown, font, available) : font;
            try
            {
                SizeF measured = graphics.MeasureString(shown, displayedFont, PointF.Empty, StringFormat.GenericTypographic);
                if (background.A != 0) using (Brush backBrush = new SolidBrush(Opaque(background))) graphics.FillRectangle(backBrush, x, y, Math.Max(1F, measured.Width), Math.Max(1F, measured.Height));
                using (Brush textBrush = new SolidBrush(Opaque(foreground))) graphics.DrawString(shown, displayedFont, textBrush, x, y, StringFormat.GenericTypographic);
            }
            finally { if (!object.ReferenceEquals(displayedFont, font)) displayedFont.Dispose(); }
        }

        private static void DrawCenteredTextBlock(Graphics graphics, string text, Font font, Color foreground, Color background, float centerX, float y)
        {
            string shown = LanguageManager.T(text ?? string.Empty);
            float symmetricWidth = Math.Max(32F, 2F * Math.Min(centerX - graphics.VisibleClipBounds.Left, graphics.VisibleClipBounds.Right - centerX) - 24F);
            Font displayedFont = FitPreviewFont(graphics, shown, font, symmetricWidth);
            try
            {
                SizeF measured = graphics.MeasureString(shown, displayedFont, PointF.Empty, StringFormat.GenericTypographic);
                DrawTextBlock(graphics, shown, displayedFont, foreground, background, centerX - measured.Width / 2F, y);
            }
            finally { if (!object.ReferenceEquals(displayedFont, font)) displayedFont.Dispose(); }
        }

        private void Fill(Graphics graphics, Color color)
        {
            using (Brush brush = new SolidBrush(Opaque(color))) graphics.FillRectangle(brush, ClientRectangle);
        }

        private static string ValueAtOrRepeatLast(List<string> values, int index, string fallback)
        {
            if (values == null || values.Count == 0 || index < 0) return fallback;
            return index < values.Count ? values[index] : fallback;
        }

        private List<string> PadPreviewValues(List<string> values, int minimumCount)
        {
            List<string> padded = values == null ? new List<string>() : new List<string>(values);
            int count = padded.Count;
            if (count > 0 && _snapshot.ChangeTextFillMode != 0)
            {
                while (padded.Count < minimumCount)
                {
                    int index = _snapshot.ChangeTextFillMode == 4 ? padded.Count % count : count - 1;
                    padded.Add(padded[index]);
                }
            }
            return padded;
        }

        private static bool HasAnimatedText(List<PreviewTextItem> items)
        {
            foreach (PreviewTextItem item in items) if (item.Rainbow || item.Blink) return true;
            return false;
        }

        private static bool IsRainbowKind(PreviewKind kind)
        {
            return kind == PreviewKind.Windows7Rainbow || kind == PreviewKind.ModernRainbow;
        }

        private static Color VgaColor(int value)
        {
            Color[] colors =
            {
                Color.FromArgb(0, 0, 0), Color.FromArgb(0, 0, 170), Color.FromArgb(0, 170, 0), Color.FromArgb(0, 170, 170),
                Color.FromArgb(170, 0, 0), Color.FromArgb(170, 0, 170), Color.FromArgb(170, 85, 0), Color.FromArgb(192, 192, 192),
                Color.FromArgb(128, 128, 128), Color.FromArgb(85, 85, 255), Color.FromArgb(85, 255, 85), Color.FromArgb(85, 255, 255),
                Color.FromArgb(255, 85, 85), Color.FromArgb(255, 85, 255), Color.FromArgb(255, 255, 85), Color.FromArgb(255, 255, 255)
            };
            return colors[value & 0x0F];
        }

        private static Color Opaque(Color color)
        {
            return Color.FromArgb(255, color.R, color.G, color.B);
        }

        private static Color FromHsv(double hue, double saturation, double value)
        {
            double chroma = value * saturation;
            double h = hue / 60.0;
            double x = chroma * (1.0 - Math.Abs((h % 2.0) - 1.0));
            double r = 0, g = 0, b = 0;
            if (h < 1) { r = chroma; g = x; }
            else if (h < 2) { r = x; g = chroma; }
            else if (h < 3) { g = chroma; b = x; }
            else if (h < 4) { g = x; b = chroma; }
            else if (h < 5) { r = x; b = chroma; }
            else { r = chroma; b = x; }
            double m = value - chroma;
            return Color.FromArgb(255, (int)Math.Round((r + m) * 255), (int)Math.Round((g + m) * 255), (int)Math.Round((b + m) * 255));
        }
    }

    internal sealed class ChangeTextEditor : UserControl
    {
        private readonly FlowLayoutPanel _rows;
        private readonly Label _count;
        private readonly CheckBox _skipPercent;
        private readonly ComboBox _fillMode;
        private readonly Label _fixedWarning;
        private readonly TrackBar _renderSpeed;
        private readonly Label _renderSpeedLabel;
        private readonly List<ChangeTextRow> _items = new List<ChangeTextRow>();
        private int _renderSpeedDragStart;
        public Func<bool> IsFailedOperationSet;

        public ChangeTextEditor()
        {
            Size = new Size(656, 352);
            Label fillModeLabel = Ui.Label("填充方式", 9F, FontStyle.Regular, Ui.Muted);
            fillModeLabel.Location = new Point(0, 2);
            Controls.Add(fillModeLabel);
            _fillMode = new ComboBox
            {
                Location = new Point(0, 32),
                Size = new Size(280, 30),
                DropDownStyle = ComboBoxStyle.DropDownList,
                BackColor = Ui.Input,
                ForeColor = Ui.Text,
                Font = new Font("Segoe UI", 9.5F),
                DropDownWidth = 600
            };
            _fillMode.Items.AddRange(new object[] { "顺序替换 (不足则保留原文)", "重复最后一条 (不足则重复最后一条)", "循环使用全部 (不足则循环使用字符串列表)", "固定位置 (一条原始文本固定对应一条字符串) (彩虹蓝屏专用)" });
            _fillMode.SelectedIndex = 0;
            _fillMode.SelectedIndexChanged += delegate { OnChanged(); };
            Controls.Add(_fillMode);
            _skipPercent = Ui.CheckBox("跳过包含 % 的原始字符串", false);
            _skipPercent.Location = new Point(_fillMode.Right + 16, 33);
            _skipPercent.CheckedChanged += delegate { OnChanged(); };
            Controls.Add(_skipPercent);
            _renderSpeedLabel = Ui.Label(string.Empty, 8.5F, FontStyle.Regular, Ui.Muted);
            Controls.Add(_renderSpeedLabel);
            _renderSpeed = new TrackBar
            {
                Minimum = 1,
                Maximum = 100,
                TickStyle = TickStyle.None,
                SmallChange = 1,
                LargeChange = 1,
                AutoSize = false,
                Height = 40,
                BackColor = Ui.Card
            };
            _renderSpeed.ValueChanged += delegate { SnapRenderSpeed(); UpdateRenderSpeedLabel(); };
            _renderSpeed.MouseDown += delegate { _renderSpeedDragStart = _renderSpeed.Value; };
            _renderSpeed.MouseUp += delegate
            {
                if (_renderSpeed.Value > _renderSpeedDragStart && _skipPercent.Checked) LanguageManager.Show(FindForm(), "勾选「跳过包含 % 的原始字符串」会导致渲染速度变得很慢，增加渲染数量也无法提升速度。\n如果需要更快的渲染速度，请取消勾选该选项。", "渲染速度提示", MessageBoxButtons.OK, MessageBoxIcon.Information);
            };
            Controls.Add(_renderSpeed);
            Layout += delegate { LayoutRenderSpeed(); };
            _fixedWarning = Ui.Label("固定位置模式下，预览文本可能与真实替换的文本不一致。", 8.5F, FontStyle.Regular, Ui.Amber);
            _fixedWarning.Location = new Point(0, 66);
            _fixedWarning.Visible = false;
            Controls.Add(_fixedWarning);
            _rows = new FlowLayoutPanel
            {
                Location = new Point(0, 90),
                Size = new Size(656, 208),
                Anchor = AnchorStyles.Top | AnchorStyles.Bottom | AnchorStyles.Left | AnchorStyles.Right,
                AutoScroll = true,
                FlowDirection = FlowDirection.TopDown,
                WrapContents = false,
                BackColor = Ui.Window,
                Padding = new Padding(8)
            };
