            minus.Click += delegate { RemoveLast(); OnChanged(); };
            Controls.Add(minus);
            ModernButton plus = new ModernButton { AutoEllipsis = true, Padding = Padding.Empty, Text = "+", Location = new Point(minus.Right + 8, minus.Top), Size = new Size(42, 38), BaseColor = Ui.CardAlt, Anchor = AnchorStyles.Bottom | AnchorStyles.Left };
            plus.Click += delegate { AddRow(null); OnChanged(); };
            Controls.Add(plus);
            _count = Ui.Label("0 / 100", 9F, FontStyle.Bold, Ui.Muted);
