        }

        public bool FixedSelected { get { return _fillMode.SelectedIndex == 3; } }
        public int SelectedMode { get { return (_skipPercent.Checked ? 1 : 0) | (_fillMode.SelectedIndex << 1); } }
        public int RenderCount { get { return _fillMode.SelectedIndex == 0 ? _items.Count : Math.Max(_items.Count, Math.Min(100, _renderSpeed.Value)); } }

        public List<string> GetPreviewTexts()
        {
            List<string> values = new List<string>();
            foreach (ChangeTextRow row in _items) values.Add(FixedSelected ? row.Value : MainForm.ValidateProtocolText(row.Value, true));
            return values;
        }

        public void LoadTexts(IList<string> texts, int mode, int renderCount = 0)
        {
            foreach (ChangeTextRow row in _items)
            {
                _rows.Controls.Remove(row);
                row.Dispose();
            }
            _items.Clear();
            if (texts == null || texts.Count == 0) AddRow(string.Empty);
            else foreach (string text in texts) AddRow(text);
            _skipPercent.Checked = (mode & 1) != 0;
            int fillMode = Math.Max(0, Math.Min(3, (mode & 6) >> 1));
            if (_fillMode.SelectedIndex != fillMode) _fillMode.SelectedIndex = fillMode;
            RefreshRows();
            _renderSpeed.Value = renderCount > 0 ? Math.Max(_renderSpeed.Minimum, Math.Min(100, renderCount)) : _renderSpeed.Minimum;
            UpdateRenderSpeedLabel();
        }

        private void AddRow(string text)
        {
            if (_items.Count >= 100) return;
            ChangeTextRow row = new ChangeTextRow(text ?? string.Empty);
            row.RemoveRequested += delegate { RemoveRow(row); };
            row.ValueEdited += delegate { OnChanged(); };
            _items.Add(row);
            _rows.Controls.Add(row);
            RefreshRows();
        }

        private void RemoveLast()
        {
            if (_items.Count > 1) RemoveRow(_items[_items.Count - 1]);
        }

        private void RemoveRow(ChangeTextRow row)
        {
            if (_items.Count <= 1) return;
            _items.Remove(row);
            _rows.Controls.Remove(row);
            row.Dispose();
            RefreshRows();
        }

        private void RefreshRows()
        {
            for (int i = 0; i < _items.Count; i++)
            {
                _items[i].Index = i + 1;
                _items[i].Hint = BuildRowHint(i);
                _items[i].HintVisible = FixedSelected;
            }
            _count.Text = _items.Count.ToString(CultureInfo.InvariantCulture) + " / 100";
            Ui.ResizeRows(_rows, 1);
            RefreshRenderSpeed();
        }

        private void RefreshRenderSpeed()
        {
            int count = _items.Count;
            int step = RenderSpeedStep;
            _renderSpeed.Maximum = 100;
            _renderSpeed.Minimum = count > 100 ? 100 : count;
            _renderSpeed.SmallChange = step;
            _renderSpeed.LargeChange = step;
            if (_renderSpeed.Value < _renderSpeed.Minimum) _renderSpeed.Value = _renderSpeed.Minimum;
            else if (_renderSpeed.Value > 100) _renderSpeed.Value = 100;
            SnapRenderSpeed();
            _renderSpeed.Enabled = count < 100 && (!FixedSelected || count >= FixedMinCount);
            if (!_renderSpeed.Enabled) _renderSpeed.Value = _renderSpeed.Minimum;
            UpdateRenderSpeedLabel();
        }

        private int RenderSpeedStep
        {
            get
            {
                int count = _items.Count;
                return _fillMode.SelectedIndex == 2 && count > 0 ? count : 1;
            }
        }

        private void SnapRenderSpeed()
        {
            int step = RenderSpeedStep;
            if (step <= 1) return;
            int value = _renderSpeed.Value;
            int min = _renderSpeed.Minimum;
            int max = _renderSpeed.Maximum;
            int lower = min + (value - min) / step * step;
            if (lower > max) lower = max;
            int upper = lower + step;
            if (upper > max) upper = max;
            int snapped = value - lower <= upper - value ? lower : upper;
            if (snapped != value) _renderSpeed.Value = snapped;
        }

        private static readonly int FixedMinCount = GetFixedMinCount();
        private static readonly string FixedMinText = GetFixedMinText();

        private static int GetFixedMinCount()
        {
            int[] version = Program.GetSystemVersion();
            if (version[0] == 6 && (version[1] == 2 || version[1] == 3)) return 8;
            if (version[0] >= 10 && Program.IsWindows11NewBlueScreen()) return 4;
            return 10;
        }

        private static string GetFixedMinText()
        {
            int[] version = Program.GetSystemVersion();
            if (version[0] == 6 && (version[1] == 2 || version[1] == 3)) return "Windows 8 至少需要 8 条文本才能使用渲染速度";
            if (version[0] >= 10 && Program.IsWindows11NewBlueScreen()) return "Windows 11 新版至少需要 4 条文本才能使用渲染速度";
            if (version[0] >= 10 && version[2] >= 22000) return "Windows 11 至少需要 10 条文本才能使用渲染速度";
            return "Windows 10 至少需要 10 条文本才能使用渲染速度";
        }

        private void UpdateRenderSpeedLabel()
        {
            if (_items.Count >= 100) _renderSpeedLabel.Text = "已达到最快渲染速度";
            else if (FixedSelected && _items.Count < FixedMinCount) _renderSpeedLabel.Text = FixedMinText;
            else _renderSpeedLabel.Text = "渲染速度: " + _renderSpeed.Value.ToString(CultureInfo.InvariantCulture);
        }

        private void LayoutRenderSpeed()
        {
            int left = _skipPercent.Left + _skipPercent.PreferredSize.Width + 18;
            int width = ClientSize.Width - left - 10;
            bool visible = _fillMode.SelectedIndex != 0 && width >= 90;
            _renderSpeed.Visible = visible;
            _renderSpeedLabel.Visible = visible;
            if (!visible) return;
            _renderSpeedLabel.Location = new Point(left, 2);
            _renderSpeedLabel.BringToFront();
            _renderSpeed.Location = new Point(left, 32);
            _renderSpeed.Size = new Size(width, 30);
        }

        private void OnChanged()
        {
            _fixedWarning.Visible = FixedSelected;
            foreach (ChangeTextRow row in _items) row.HintVisible = FixedSelected;
            RefreshRenderSpeed();
            LayoutRenderSpeed();
        }

        private string BuildRowHint(int index)
        {
            bool windows11New = !Program.ForceWindows10BlueScreenEffect && Program.IsWindows11NewBlueScreen();
            bool failedOperation = IsFailedOperationSet != null && IsFailedOperationSet();
            if (windows11New)
            {
                if (index == 0) return "你的设备遇到问题，需要重启。";
                if (index == 1) return "(终止代码整行)";
                if (index == 2) return failedOperation ? "(失败的操作整行)" : "0% 完成";
                if (index == 3 && failedOperation) return "0% 完成";
                return "(对应百分比)";
            }
            if (Program.IsWindows8())
            {
                switch (index)
                {
                    case 0: return ":(";
                    case 1: return "你的电脑遇到问题，需要重新启动。";
                    case 2: return "我们只收集某些错误信息，然后为你重新启动。";
                    case 3: return "如果你想了解更多信息，则可以稍后在线搜索此错误:";
                    case 4: return "(对应蓝屏终止代码)";
                    case 5: return "(完成";
                    case 6: return "(对应百分比)";
                    case 7: return "% )";
                    default: return "(对应百分比)";
                }
            }
            switch (index)
            {
                case 0: return ":(";
                case 1: return "你的电脑遇到问题，需要重启。";
                case 2: return "我们只收集某些错误信息，然后为你重新启动。";
                case 3: return "有关此问题的详细信息和可能的解决方法，请访问:";
                case 4: return "https://www.windows.com/stopcode";
                case 5: return "如果致电支持人员，请向他们提供以下信息:";
                case 6: return "终止代码:";
                case 7: return "(对应蓝屏终止代码)";
                case 8: return failedOperation ? "失败的操作:" : "(对应百分比)";
                case 9: return failedOperation ? "(对应失败的操作的驱动)" : "% 完成";
                case 10: return "(对应百分比)";
                case 11: return failedOperation ? "% 完成" : "(对于百分比)";
                default: return "(对应百分比)";
            }
        }
    }

    internal sealed class ChangeTextPage : PageView
    {
        private readonly ChangeTextEditor _editor;
        private readonly CommandRequestHandler _send;
        private readonly PreviewRequestHandler _preview;
        private readonly Func<bool> _failedOperationSet;
        private readonly List<string> _appliedPreviewTexts = new List<string>();
        private int _appliedMode;
        private int _appliedTargetCount;
        public bool HasPreviewConfiguration { get; private set; }
        public bool SkipPercent { get { return (_appliedMode & 1) != 0; } }
        public int FillMode { get { int mode = _appliedMode & 6; return mode == 6 ? 0 : mode; } }

        public ChangeTextPage(CommandRequestHandler send, PreviewRequestHandler preview, Func<bool> failedOperationSet) : base("替换文本", "配置蓝屏显示文本；可设置 1–100 条")
        {
            _send = send;
            _preview = preview;
            _failedOperationSet = failedOperationSet;
            CardPanel card = new CardPanel { Size = new Size(700, 486) };
            Label title = Ui.Label("ChangeText 替换蓝屏文本", 13F, FontStyle.Bold, Ui.Text);
            title.Location = new Point(22, 18);
            card.Controls.Add(title);
            _editor = new ChangeTextEditor { IsFailedOperationSet = failedOperationSet, Location = new Point(22, 52), Size = new Size(656, 352) };
            _editor.Anchor = AnchorStyles.Top | AnchorStyles.Bottom | AnchorStyles.Left | AnchorStyles.Right;
            card.Controls.Add(_editor);
            ModernButton apply = new ModernButton { Text = "应用全部替换文本", Size = new Size(168, 42), Anchor = AnchorStyles.Bottom | AnchorStyles.Right };
            apply.Location = new Point(card.ClientSize.Width - apply.Width - 22, 414);
            apply.Click += delegate { Apply(); };
            card.Controls.Add(apply);
            ModernButton previewButton = new ModernButton { Text = "预览", Size = new Size(100, 42), BaseColor = Ui.CardAlt, Anchor = AnchorStyles.Bottom | AnchorStyles.Right };
            previewButton.Location = new Point(apply.Left - previewButton.Width - 12, apply.Top);
            previewButton.Click += delegate
            {
                try
                {
                    PreviewSnapshot snapshot = PreviewSnapshot.CreateDefault(false);
                    FillChangeTextSnapshot(snapshot);
                    snapshot.Kind = PreviewKind.ModernChangeText;
                    _preview(snapshot, "替换文本预览");
                }
                catch (Exception ex)
                {
                    LanguageManager.Show(FindForm(), ex.Message, "无法生成预览", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                }
            };
            card.Controls.Add(previewButton);
            AddCard(card, true);
        }

        private void FillChangeTextSnapshot(PreviewSnapshot snapshot)
        {
            snapshot.ReplacementTexts.AddRange(_editor.GetPreviewTexts());
            snapshot.SkipPercent = (_editor.SelectedMode & 1) != 0;
            snapshot.ChangeTextFillMode = _editor.FixedSelected ? 0 : (_editor.SelectedMode & 6);
        }

        public List<string> GetAppliedPreviewTexts()
        {
            return new List<string>(_appliedPreviewTexts);
        }

        public string BuildAppliedProtocolCommand(bool forceWindows10Layout, bool failedOperationSet)
        {
            if (!HasPreviewConfiguration) return null;
            return BuildProtocolCommand(_appliedPreviewTexts, _appliedMode, forceWindows10Layout, failedOperationSet, _appliedTargetCount);
        }

        private static void AppendHexUtf16(StringBuilder command, string value)
        {
            foreach (char ch in value) command.Append(((int)ch).ToString("X4", CultureInfo.InvariantCulture));
        }

        internal static string BuildProtocolCommand(IList<string> values, int mode, bool forceWindows10Layout, bool failedOperationSet, int renderCount)
        {
            int fillMode = (mode & 6) >> 1;
            int target = fillMode == 0 ? values.Count : Math.Max(values.Count, Math.Min(100, renderCount));
            List<string> padded = new List<string>(values);
            if (fillMode == 1 && values.Count > 0)
            {
                string last = values[values.Count - 1];
                while (padded.Count < target) padded.Add(last);
            }
            else if (fillMode == 2 && values.Count > 0)
            {
                while (padded.Count < target) padded.AddRange(values);
            }
            else if (fillMode == 3)
            {
                while (padded.Count < target) padded.Add(string.Empty);
            }
            bool skipPercent = (mode & 1) != 0;
            int[] version = Program.GetSystemVersion();
            bool windows10Layout = forceWindows10Layout || (version[2] < 26100 && version[0] <= 10);
            if ((mode & 6) == 6)
            {
                StringBuilder fixedCommand = new StringBuilder("CT ");
                fixedCommand.Append(mode.ToString(CultureInfo.InvariantCulture));
                if (windows10Layout)
                {
                    int placeholderCount = skipPercent ? (Program.IsWindows8() ? 202 : 101) : (Program.IsWindows8() ? 303 : 202);
                    fixedCommand.Append(" \"\u001fCT:3:");
                    fixedCommand.Append(placeholderCount.ToString(CultureInfo.InvariantCulture));
                    fixedCommand.Append('"');
                }
                else fixedCommand.Append(" \"\u001fCT:1:").Append(failedOperationSet ? "2" : "1").Append('"');
                foreach (string value in padded)
                {
                    if (value.IndexOf('\0') >= 0 || value.Length * 4 + 5 > 32760) throw new ArgumentException("固定位置模式的文本不能含 NUL，单条文本不能超过 8188 个 UTF-16 字符。");
                    fixedCommand.Append(" \"\u001fU16:");
                    AppendHexUtf16(fixedCommand, value);
                    fixedCommand.Append('"');
                }
                return fixedCommand.ToString();
            }
            StringBuilder command = new StringBuilder();
            command.Append("CT ");
            command.Append(mode.ToString(CultureInfo.InvariantCulture));
            if (windows10Layout)
            {
                int placeholderCount = skipPercent ? (Program.IsWindows8() ? 202 : 101) : (Program.IsWindows8() ? 303 : 202);
                command.Append(" \"\u001fCT:3:");
                command.Append(placeholderCount.ToString(CultureInfo.InvariantCulture));
                command.Append('"');
            }
            else command.Append(" \"\u001fCT:1:").Append(failedOperationSet ? "2" : "1").Append('"');
            for (int i = 0; i < padded.Count; i++)
            {
                command.Append(" \"");
                command.Append(padded[i]);
                command.Append('"');
            }
            return command.ToString();
        }

        private void Apply()
        {
            try
            {
                List<string> values = _editor.GetPreviewTexts();
                int mode = _editor.SelectedMode;
                int renderCount = _editor.RenderCount;
                string command = BuildProtocolCommand(values, mode, Program.ForceWindows10BlueScreenEffect, _failedOperationSet != null && _failedOperationSet(), renderCount);
                if (_send(command, "替换文本配置已设置\n"))
                {
                    _appliedPreviewTexts.Clear();
                    _appliedPreviewTexts.AddRange(values);
                    _appliedMode = mode;
                    _appliedTargetCount = renderCount;
                    HasPreviewConfiguration = true;
                }
            }
            catch (Exception ex)
            {
                LanguageManager.Show(FindForm(), ex.Message, "文本格式无效", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        }
    }

