    internal sealed class QrConfiguration
    {
        private readonly int _width;
        private readonly int _length;
        private readonly uint[] _pixels;

        public QrConfiguration(int width, int length, uint[] pixels)
        {
            _width = width;
            _length = length;
            _pixels = pixels;
        }

        public long PixelCount { get { return _pixels.LongLength; } }
        public string Dimensions { get { return _width.ToString(CultureInfo.InvariantCulture) + " × " + _length.ToString(CultureInfo.InvariantCulture); } }

        public string BuildCommand()
        {
            StringBuilder command = new StringBuilder(32 + (_pixels.Length * 9));
            command.Append("QR ");
            command.Append(_width.ToString("X", CultureInfo.InvariantCulture));
            command.Append(' ');
            command.Append(_length.ToString("X", CultureInfo.InvariantCulture));
            command.Append(" {");
            for (int i = 0; i < _pixels.Length; i++)
            {
                if (i > 0) command.Append(',');
                command.Append(_pixels[i].ToString("X8", CultureInfo.InvariantCulture));
            }
            command.Append('}');
            return command.ToString();
        }

        public void ApplyToPreview(PreviewSnapshot snapshot)
        {
            snapshot.QrWidth = _width;
            snapshot.QrLength = _length;
            snapshot.QrPixels = (uint[])_pixels.Clone();
        }
    }

